import appIcon from '../../../assets/branding/iqdi-app-icon.svg?url';
import markOriginal from '../../../assets/branding/iqdi-mark-original.svg?url';
import markDark from '../../../assets/branding/iqdi-mark-dark.svg?url';
import logoOriginal from '../../../assets/branding/iqdi-logo-original.svg?url';
import logoDark from '../../../assets/branding/iqdi-logo-dark.svg?url';
import { useTheme } from './hooks.ts';

/**
 * The one IQDI brand component. The vector masters live in assets/branding/ (generated by
 * tools/branding/generate_brand.py); pages never copy logo artwork themselves.
 *  - symbol: simplified app icon (palm + arch + two rivers, no lion, no text) — headers, ≤ 64 px
 *  - mark:   full symbol (palm, arch with one lion, two rivers) — about/branding areas
 *  - logo:   mark + «IQDI» + «الهوية الرقمية العراقية» — welcome / introductory screens
 * Original or Dark artwork follows the active theme unless `tone` fixes it. TEST ONLY project:
 * the label never implies government endorsement.
 */
export type IQDIBrandVariant = 'symbol' | 'mark' | 'logo';
export const IQDI_BRAND_LABEL = 'IQDI — الهوية الرقمية العراقية (نموذج تجريبي)';

const ART: Record<IQDIBrandVariant, { light: string; dark: string; ratio: number }> = {
  symbol: { light: appIcon, dark: appIcon, ratio: 1 },
  mark: { light: markOriginal, dark: markDark, ratio: 810 / 1040 },
  logo: { light: logoOriginal, dark: logoDark, ratio: 1372 / 1040 },
};

export function IQDIBrand({ variant = 'symbol', size = 40, tone = 'auto', label = IQDI_BRAND_LABEL, decorative = false, className }: {
  variant?: IQDIBrandVariant;
  /** Rendered width in CSS px; height follows the artwork's aspect ratio. */
  size?: number;
  tone?: 'auto' | 'light' | 'dark';
  label?: string;
  /** True when adjacent text already names the product (e.g. the header), so screen readers do not hear it twice. */
  decorative?: boolean;
  className?: string;
}) {
  const { resolvedTheme } = useTheme();
  const art = ART[variant];
  const t = tone === 'auto' ? resolvedTheme : tone;
  return (
    <img
      className={`iqdi-brand iqdi-brand--${variant}${className ? ` ${className}` : ''}`}
      src={t === 'dark' ? art.dark : art.light}
      width={size}
      height={Math.round(size * art.ratio)}
      alt={decorative ? '' : label}
      aria-hidden={decorative ? true : undefined}
      data-tone={t}
      decoding="async"
      draggable={false}
    />
  );
}
